sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_GetReferenceQualifierSubdivisionsByCountry(vCountry,vExpected)
	{
		function TestCase_GetReferenceQualifierSubdivisionsByCountry_CheckResult(vInput,vExpected,vResult)
		{
			return (vExpected == vResult);
		}
		
		test.TestCase(
			'Function GetReferenceQualifierSubdivisionsByCountry()',
			GetReferenceQualifierSubdivisionsByCountry,
			{
				'vCountry': vCountry
			},
			vExpected,
			TestCase_GetReferenceQualifierSubdivisionsByCountry_CheckResult);
	}
		
	TestCase_GetReferenceQualifierSubdivisionsByCountry(null,'');

	var grCountry = new GlideRecord('core_country');
	grCountry.initialize();
	grCountry.iso3166_3 = 'XXX';
	grCountry.name = 'X-Land';
	x_snc_devtools.GlideRecordInsert(grCountry);

	TestCase_GetReferenceQualifierSubdivisionsByCountry(grCountry,'');

	var grSubdivision = new GlideRecord('x_snc_geodata_country_subdivision');
	grSubdivision.initialize();
	grSubdivision.iso_3166_2_code = 'YY';
	grSubdivision.name = 'Region Y';
	grSubdivision.country = grCountry.sys_id;
	x_snc_devtools.GlideRecordInsert(grSubdivision);
	test.Log(grSubdivision);

	TestCase_GetReferenceQualifierSubdivisionsByCountry(grCountry,'sys_id=' + grSubdivision.sys_id);



	
	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
